from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiry_date = None
        self.no_replacement_today = False

    def OnData(self, slice: Slice):
        # Feed only actual SPY minute bars into the consolidator.
        # Missing minutes produce no synthetic or forward-filled bars.
        if self.spy in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy])

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationAndTimeStop(slice)
        self.HandleProfitTarget(slice)
        self.HandlePendingEntry(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        # The equity subscription uses New York time, so these boundaries
        # align to 09:30-09:35, 09:35-09:40, etc.
        if bar.Symbol != self.spy:
            return

        if not self.fast.IsReady:
            self.fast.Update(bar.EndTime, bar.Close)
            self.slow.Update(bar.EndTime, bar.Close)
            return

        prior_fast = self.fast.Current.Value
        prior_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        bullish_cross = (
            prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self.pending_signal = True

    def HandlePendingEntry(self, slice: Slice):
        if not self.pending_signal:
            return

        # Evaluate exactly once for this completed-bar signal.
        self.pending_signal = False

        if self.no_replacement_today:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity != 0:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        expiry = expirations[0]
        threshold = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected.Symbol
        self.expiry_date = expiry
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.held_option, 1)

        self.Debug(
            f"{self.Time}: submitted entry for {self.held_option.Value}"
        )

    def HandleProfitTarget(self, slice: Slice):
        if self.held_option is None:
            return

        if self.entry_price is None:
            return

        security = self.Securities[self.held_option]
        if not security.Invested:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_option, -quantity
                )
                self.Debug(
                    f"{self.Time}: profit target exit submitted for "
                    f"{self.held_option.Value}"
                )

    def HandleExpirationAndTimeStop(self, slice: Slice):
        if self.held_option is None or self.expiry_date is None:
            return

        security = self.Securities[self.held_option]
        if not security.Invested:
            return

        current_date = self.Time.date()

        # Safety liquidation once expiration processing begins.
        if current_date >= self.expiry_date:
            self.no_replacement_today = True
            self.CancelOpenExitOrder()
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0 and (
                self.exit_ticket is None or not self.IsOpen(self.exit_ticket)
            ):
                self.exit_ticket = self.MarketOrder(
                    self.held_option, -quantity
                )
                self.Debug(
                    f"{self.Time}: expiration safety exit submitted for "
                    f"{self.held_option.Value}"
                )
            return

        preceding_trading_day = self.PrecedingTradingDay(self.expiry_date)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.CancelOpenExitOrder()
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0 and (
                self.exit_ticket is None or not self.IsOpen(self.exit_ticket)
            ):
                self.exit_ticket = self.MarketOrder(
                    self.held_option, -quantity
                )
                self.Debug(
                    f"{self.Time}: time-stop exit submitted for "
                    f"{self.held_option.Value}"
                )

    def HandleUnexpectedEquityPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        self.no_replacement_today = True
        quantity = self.Portfolio[self.spy].Quantity
        self.MarketOrder(self.spy, -quantity)
        self.Debug(
            f"{self.Time}: unexpected SPY exercise/assignment position; "
            f"liquidation submitted"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"{self.Time}: entry filled at "
                        f"{self.entry_price:.4f}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None
                    self.held_option = None
                    self.expiry_date = None
                    self.entry_price = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: exit filled at "
                        f"{order_event.FillPrice:.4f}"
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.expiry_date = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False) or \
           getattr(order_event, "IsExercise", False):
            self.no_replacement_today = True
            self.Debug(
                f"{self.Time}: unexpected option exercise/assignment event"
            )

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

    @staticmethod
    def IsOpen(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.PartiallyFilled,
            OrderStatus.Submitted
        )

    def PrecedingTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnEndOfDay(self, symbol):
        if symbol == self.spy:
            self.no_replacement_today = False
